insert into public.signals (id, kind, title, description, state, lat, lon, radius_km, highways, starts_at, ends_at, severity, transit_multiplier, source, provenance, short_label, supply_cut_pct, affects) values
  ('sig-rain-veracruz', 'weather', 'Heavy rain and landslide risk, central Veracruz', 'Late rainy season: saturated slopes on the Orizaba–Puebla stretch of MEX-150D. Trucks queue at partial closures and transit from Orizaba stretches from 2 to about 5 days.', 'Veracruz', 18.85, -97.1, 90, ARRAY['MEX-150D']::text[], '2026-09-28', '2026-10-20', 'high', 2.6, 'SMN/CONAGUA seasonal outlook (seeded for demo)', 'estimated', 'Rainy season', DEFAULT, DEFAULT),
  ('sig-hurricane-gulf', 'weather', 'Hurricane watch, Gulf of Mexico coast', 'A tropical system is forecast to approach the Veracruz coast; heavy rain inland on 8–12 Oct. A watch, not a warning.', 'Veracruz', 19.2, -96.13, 120, '{}'::text[], '2026-10-08', '2026-10-12', 'medium', 1.3, 'SMN tropical cyclone bulletin (seeded for demo)', 'estimated', 'Hurricane watch', DEFAULT, DEFAULT),
  ('sig-closure-57d', 'road', 'Road closure, MEX-57D near Palmillas', 'Lane closure for bridge repair; trucks are diverted for a few hours at a time.', 'Querétaro', 20.37, -99.95, 25, ARRAY['MEX-57D']::text[], '2026-10-03', '2026-10-08', 'medium', 1.3, 'Capufe / SCT road report (seeded for demo)', 'estimated', 'Partial closure on MEX-57D', DEFAULT, DEFAULT),
  ('sig-blockade-puebla', 'blockade', 'Highway blockade, Puebla–Tlaxcala corridor', 'Community blockade on MEX-119 and MEX-190 near Amozoc. Cargo is held or rerouted through side roads.', 'Puebla', 19.05, -98.05, 60, ARRAY['MEX-119','MEX-190']::text[], '2026-10-04', '2026-10-09', 'medium', 1.7, 'Local news and carrier reports (seeded for demo)', 'estimated', 'Highway blockade near Puebla and Tlaxcala', DEFAULT, DEFAULT),
  ('sig-theft-45d57d', 'theft', 'Cargo theft hotspot, MEX-45D / MEX-57D at night', 'Reported hijackings on the Celaya–Querétaro and Querétaro–San Luis Potosí stretches between 20:00 and 05:00. Carriers add escorts or hold trucks until daylight.', 'Guanajuato', 20.5, -100.6, 70, ARRAY['MEX-45D','MEX-57D']::text[], '2026-09-20', '2026-11-15', 'medium', 1.06, 'Carrier incident reports (seeded for demo)', 'estimated', 'Night cargo theft on MEX-45D / MEX-57D', DEFAULT, DEFAULT),
  ('sig-port-manzanillo', 'port', 'Container congestion, Port of Manzanillo', 'Yard saturation and customs queues delay container release by 3–5 days; imported resin reaches the supplier late and outbound loads slip.', 'Colima', 19.05, -104.32, 80, ARRAY['MEX-200']::text[], '2026-09-25', '2026-10-18', 'medium', 1.5, 'API Manzanillo terminal notice (seeded for demo)', 'estimated', 'Port congestion at Manzanillo', DEFAULT, DEFAULT),
  ('sig-press-edl', 'supplier', 'Press 4 breakdown, Estampados del Laja', 'Die change overran on Press 4 (400 t). Output is being recovered with overtime; outbound shipments leave later in the day, and more of them at night.', 'Guanajuato', 20.52, -100.81, 5, '{}'::text[], '2026-10-04', '2026-10-12', 'medium', 1.3, 'Supplier-reported through FlowTwin (seeded for demo)', 'estimated', 'Press 4 unplanned stop at Estampados del Laja', DEFAULT, DEFAULT),
  ('sig-rain-toluca', 'weather', 'Heavy afternoon rain, Toluca valley', 'Daily storms flood low-lying roads around Toluca and slow trucks on MEX-15D.', 'México', 19.29, -99.65, 50, '{}'::text[], '2026-09-30', '2026-10-15', 'low', 1.1, 'SMN daily forecast (seeded for demo)', 'estimated', 'Heavy rain in the Toluca valley', DEFAULT, DEFAULT),
  ('sig-customs-nld', 'customs', 'Customs system outage, Nuevo Laredo commercial bridge', 'Repeated failures of the customs system slowed the release of cargo at the Nuevo Laredo commercial bridge. Trucks queue for kilometres and the backlog clears slowly; release takes about three times longer. Modelled on press reports of ANAM outages.', 'Tamaulipas', 27.5, -99.52, 25, '{}'::text[], '2026-10-03', '2026-10-20', 'high', 3.0, 'Press reports of ANAM system outages (seeded for demo)', 'estimated', 'Customs system outage at Nuevo Laredo', DEFAULT, DEFAULT),
  ('sig-season-hurricane-gulf', 'weather', 'Late hurricane season, Gulf of Mexico coast', 'Hurricane season runs to 30 November. Storms on the Gulf coast close stretches of MEX-150D and MEX-180D for a day or two at a time.', 'Veracruz', 19.2, -96.4, 200, ARRAY['MEX-150D','MEX-180D']::text[], '2026-10-21', '2026-11-30', 'medium', 1.6, 'Historical SMN hurricane season pattern (seeded for demo)', 'estimated', 'Late hurricane season on the Gulf', DEFAULT, DEFAULT),
  ('sig-season-nld-yearend', 'customs', 'Year-end cargo peak, Nuevo Laredo customs', 'Cross-border volume peaks from late November to Christmas; customs release at Nuevo Laredo usually takes longer.', 'Tamaulipas', 27.5, -99.52, 25, '{}'::text[], '2026-11-23', '2026-12-23', 'medium', 1.8, 'Historical border crossing volumes (seeded for demo)', 'estimated', 'Year-end cargo peak at Nuevo Laredo', DEFAULT, DEFAULT),
  ('sig-season-holidays-57d', 'road', 'Holiday traffic and reduced carrier capacity, MEX-57D', 'From 19 December carriers run fewer trucks and traffic on MEX-57D rises; loads take longer to book and to arrive.', 'Querétaro', 20.59, -100.39, 30, ARRAY['MEX-57D']::text[], '2026-12-19', '2027-01-04', 'low', 1.3, 'Historical holiday freight pattern (seeded for demo)', 'estimated', 'Holiday traffic on MEX-57D', DEFAULT, DEFAULT),
  ('sig-input-etb-polyol', 'supplier-input', 'Polyol shortage, Espumas y Tapizados del Bajío', 'ETB''s polyol supplier declared force majeure after a plant outage on the Gulf coast. ETB receives about 60% of its usual polyol and has cut foam output accordingly; finished goods cover the first days.', 'Guanajuato', 21.12, -101.68, 5, '{}'::text[], '2026-10-07', '2026-10-24', 'medium', 1.0, 'Supplier-reported through FlowTwin (seeded for demo)', 'estimated', 'Polyol shortage', 0.4, '{"supplierIds": ["etb"]}'::jsonb),
  ('sig-policy-resin-tariff', 'policy', 'Tariff increase on polyamide resins from countries without a trade agreement', 'Mexico raises the import tariff on polyamide (HS 3908) from countries without a trade agreement, including China and Korea, from 1 November. Importers of PA6 compound may re-source or hold stock back while the change settles.', 'Ciudad de México', 19.43, -99.13, 0, '{}'::text[], '2026-11-01', '2027-10-31', 'high', 1.0, 'Diario Oficial de la Federación decree pattern (seeded for demo)', 'estimated', 'Higher tariff on Asian polyamide', DEFAULT, '{"originCountries": ["CN", "KR"], "hsPrefixes": ["3908"]}'::jsonb)
